size_t n = points.size();
if (k > n) k = n;

auto cmp = [](const std::pair<double, std::size_t>& a,
              const std::pair<double, std::size_t>& b) {
    return a.first < b.first; // max‑heap based on distance
};

std::priority_queue<std::pair<double, std::size_t>,
                    std::vector<std::pair<double, std::size_t>>,
                    decltype(cmp)> heap(cmp);

for (std::size_t i = 0; i < n; ++i) {
    double dx = points[i].x - searchPoint.x;
    double dy = points[i].y - searchPoint.y;
    double dz = points[i].z - searchPoint.z;
    double dist2 = dx * dx + dy * dy + dz * dz;

    if (heap.size() < k) {
        heap.emplace(dist2, i);
    } else if (dist2 < heap.top().first) {
        heap.pop();
        heap.emplace(dist2, i);
    }
}

std::vector<std::size_t> result;
result.reserve(k);
while (!heap.empty()) {
    result.push_back(heap.top().second);
    heap.pop();
}
std::reverse(result.begin(), result.end());
return result;

